261	  // GET /api/projects/:slug/work-packages
262	  if (
263	    method === 'GET' &&
264	    rest.length === 3 &&
265	    rest[0] === 'projects' &&
266	    rest[2] === 'work-packages'
267	  ) {
268	    const slug = rest[1]!;
269	    return () => handleListWorkPackages(ledgerRoot, slug);
